<?php $privatePreview=$privatePreview??false; ?>
<article class="published-story"><p class="eyebrow"><?= e($story['category']??C_KINDS[$story['kind']]) ?></p><h2><?= e($story['title']) ?></h2><?php if($story['cover_asset_id']):?><figure><img src="<?= e(c_media_url((int)$story['cover_asset_id'],960,$privatePreview)) ?>" srcset="<?= e(c_media_url((int)$story['cover_asset_id'],480,$privatePreview)) ?> 480w, <?= e(c_media_url((int)$story['cover_asset_id'],960,$privatePreview)) ?> 960w, <?= e(c_media_url((int)$story['cover_asset_id'],1600,$privatePreview)) ?> 1600w" sizes="(max-width: 700px) 90vw, 800px" alt="<?= e($story['alt_text']) ?>" loading="lazy"><figcaption><?= e($story['caption']) ?><?= $story['credit']?' · '.e($story['credit']):'' ?></figcaption></figure><?php endif;?><p class="lead"><?= e($story['excerpt']) ?></p><div class="cms-prose"><?php foreach(preg_split('/\R\s*\R/',$story['body']) as $paragraph):if(trim($paragraph)!==''):?><p><?= nl2br(e($paragraph)) ?></p><?php endif;endforeach;?></div><?php if($story['video_url']):?><p><a class="text-link" href="<?= e($story['video_url']) ?>" target="_blank" rel="noopener noreferrer">Watch external video (opens a new tab) →</a></p><?php endif;?>
<?php if($privatePreview&&$story['kind']==='character'):$secret=json_decode($story['character_json'],true)?:[];?><aside class="notice"><h3>Private reveal data</h3><p><?= e($secret['actor_name']??'No actor name') ?></p><p><?= nl2br(e($secret['actor_bio']??'')) ?></p><?php if(!empty($secret['portrait_id'])):?><img src="<?= e(c_media_url((int)$secret['portrait_id'],480,true)) ?>" alt="<?= e($secret['portrait_alt']??'Private portrait') ?>" width="240"><?php endif;?></aside><?php endif;?></article>
